patterns.nginx_config:
server {
  listen 443 ssl;
  listen 443 quic reuseport;
  http2 on;
  http3 on;
  ssl_protocols TLSv1.2 TLSv1.3;
  ssl_certificate /etc/nginx/ssl/tls.crt;
  ssl_certificate_key /etc/nginx/ssl/tls.key;
  ssl_session_cache shared:SSL:10m;
  ssl_session_timeout 1d;
  ssl_session_tickets on;
  ssl_early_data on;
  quic_retry on;
  quic_gso on;
  add_header Alt-Svc 'h3=":443"; ma=86400' always;
  add_header Strict-Transport-Security 'max-age=63072000; includeSubdomains; preload' always;
  location / {
    if ($ssl_early_data) {
      # Protect non-idempotent methods from 0-RTT replay
      set $early_data_flag 1;
    }
    proxy_pass http://backend;
    proxy_set_header Early-Data $ssl_early_data;
  }
  location /api/write {
    if ($ssl_early_data) { return 425; }
    proxy_pass http://backend;
  }
}

patterns.http_snippet:
proxy_cache_path /cache/nginx levels=1:2 keys_zone=enterprise_cache:100m max_size=10g inactive=24h use_temp_path=off;
proxy_cache_key "$scheme$request_method$host$request_uri";
proxy_cache_lock on;
proxy_cache_lock_timeout 5s;
proxy_cache_use_stale error timeout updating http_500 http_502 http_503 http_504;
proxy_cache_revalidate on;

ingress_annotations.nginx.ingress.kubernetes.io/server-snipp:
proxy_cache enterprise_cache;
proxy_cache_valid 200 302 10m;
proxy_cache_valid 404 1m;
proxy_cache_min_uses 2;
add_header X-Cache-Status $upstream_cache_status;
proxy_no_cache $http_authorization;
proxy_cache_bypass $http_authorization;
